class AgoFormatter {
  format(dt) {
    const now = new Date()
    const seconds = (now - dt) / 1000
    const minutes = seconds / 60
    const hours = minutes / 60
    const days = hours / 24
    const weeks = days / 7
    const months = days / (365 / 12)
    const years = days / 365

    if (years >= 1) return tCount("time_ago.year", Math.floor(years))
    if (months >= 1) return tCount("time_ago.month", Math.floor(months))
    if (weeks >= 1) return tCount("time_ago.week", Math.floor(weeks))
    if (days >= 1) return tCount("time_ago.day", Math.floor(days))
    if (hours >= 1) return tCount("time_ago.hour", Math.floor(hours))
    if (minutes >= 1) return tCount("time_ago.minute", Math.floor(minutes))

    return t("less_than_a_minute_ago")
  }
}

class DaysAgoFormatter {
  format(date) {
    const days = differenceInDays(date, new Date())

    if (days <= 0) return styleableValue(t("today"))
    if (days === 1) return styleableValue(t("yesterday"))
    return t("days_ago", { count: styleableValue(days) })
  }
}

class DaysAgoOrWeekdayFormatter {
  constructor(weekdayFormatter) {
    this.weekdayFormatter = weekdayFormatter
  }

  format(date) {
    const days = differenceInDays(date, new Date())

    if (days <= 1) {
      return new DaysAgoFormatter().format(date)
    } else {
      return this.weekdayFormatter.format(date)
    }
  }
}

class InDaysFormatter {
  format(date) {
    const days = differenceInDays(new Date(), date)

    if (days <= 0) return styleableValue(t("today"))
    if (days === 1) return styleableValue(t("tomorrow"))
    return t("in_days", { count: styleableValue(days) })
  }
}

class TimeOrDateFormatter {
  constructor(locale) {
    this.locale = locale
  }

  format(date) {
    const days = differenceInDays(date, new Date())

    if (days >= 1) {
      return new Intl.DateTimeFormat(this.locale, { month: "short", day: "numeric" }).format(date)
    } else {
      return new Intl.DateTimeFormat(this.locale, { timeStyle: "short" }).format(date)
    }
  }
}

function styleableValue(value) {
  return `<span class="local-time-value">${value}</span>`
}
